/bin/bash -c "python3 - <<'PY'
from PIL import Image
import numpy as np
for i in [0,3,6,9,12,15,19]:
 a=np.asarray(Image.open(f'frames/{i:02d}.png').convert('RGB')).astype(float)
 # actual center x=140 colors, and cloth predicate broad central sample
 print('\\nF',i)
 for y in range(0,124,4):
  vals=[]
  for x in range(80,212,4):
   c=a[y:y+4,x:x+4].mean((0,1)); r,g,b=c
   if g>r*1.04 and g>b*1.04: vals.append('C')
   elif r>g*1.25 and g>b*1.2: vals.append('t')
   elif b>r*1.2: vals.append('B')
   elif max(c)<45: vals.append('K')
   elif max(c)>195 and min(c)>170: vals.append('W')
   elif r>g*1.1 and g>b*1.1: vals.append('c')
   else: vals.append('.')
  print(f'{y:3d} '+''.join(vals))
PY"

/bin/bash -c "python3 - <<'PY'
from PIL import Image
import numpy as np
# final coverage and row width based diff, show changed span every 4 rows
b=np.asarray(Image.open('frames/00.png').convert('RGB')).astype(int)
for i in [3,6,9,12,15,19]:
 a=np.asarray(Image.open(f'frames/{i:02d}.png').convert('RGB')).astype(int)
 d=np.abs(a-b).max(2)>12
 print('\\nF',i)
 for y in range(0,124,4):
  xs=np.where(d[y])[0]
  if len(xs): print(f'{y:3d} {len(xs):3d} {xs.min():3d}-{xs.max():3d}',end=' | ')
  else: print(f'{y:3d} 0',end=' | ')
  if y%20==16: print()
 print()
PY"
